17. use verus_state_machines_macros::tokenized_state_machine;
18. 
19. #[is_variant]
20. pub enum ProducerState {
21.     Idle(nat),  
22.     Producing(nat),
23. }
24. 
25. #[is_variant]
26. pub enum ConsumerState {
27.     Idle(nat),  
28.     Consuming(nat),
29. }
30. 
31. tokenized_state_machine!{FifoQueue<T> {
32.     fields {
33. 
34.         #[sharding(constant)]
35.         pub backing_cells: Seq<CellId>,
36. 
37. 
38.         #[sharding(storage_map)]
39.         pub storage: Map<nat, cell::PointsTo<T>>,
40. 
41. 
42.         #[sharding(variable)]
43.         pub head: nat,
44. 
45. 
46.         #[sharding(variable)]
47.         pub tail: nat,
48. 
49. 
50.         #[sharding(variable)]
51.         pub producer: ProducerState,
52. 
53. 
54.         #[sharding(variable)]
55.         pub consumer: ConsumerState,
56.     }
57. 
58.     pub open spec fn len(&self) -> nat {
59.         self.backing_cells.len()
60.     }
61. 
62.     pub open spec fn inc_wrap(i: nat, len: nat) -> nat {
63.         if i + 1 == len { 0 } else { i + 1 }
64.     }
65. 
66. 
67.     #[invariant]
68.     pub fn not_overlapping(&self) -> bool {
69.         match (self.producer, self.consumer) {
70.             (ProducerState::Producing(tail), ConsumerState::Idle(head)) => {
71.                 Self::inc_wrap(tail, self.len()) != head
72.             }
73.             (ProducerState::Producing(tail), ConsumerState::Consuming(head)) => {
74.                 head != tail
75.                 && Self::inc_wrap(tail, self.len()) != head
76.             }
77.             (ProducerState::Idle(tail), ConsumerState::Idle(head)) => {
78.                 true
79.             }
80.             (ProducerState::Idle(tail), ConsumerState::Consuming(head)) => {
81.                 head != tail
82.             }
83.         }
84.     }
85. 
86. 
87.     #[invariant]
88.     pub fn in_bounds(&self) -> bool {
89.         0 <= self.head && self.head < self.len() &&
90.         0 <= self.tail && self.tail < self.len()
91.         && match self.producer {
92.             ProducerState::Producing(tail) => {
93.                 self.tail == tail
94.             }
95.             ProducerState::Idle(tail) => {
96.                 self.tail == tail
97.             }
98.         }
99.         && match self.consumer {
100.             ConsumerState::Consuming(head) => {
101.                 self.head == head
102.             }
103.             ConsumerState::Idle(head) => {
104.                 self.head == head
105.             }
106.         }
107.     }
108. 
109. 
110.     pub open spec fn in_active_range(&self, i: nat) -> bool {
111.         0 <= i && i < self.len() && (
112.             if self.head <= self.tail {
113.                 self.head <= i && i < self.tail
114.             } else {
115.                 i >= self.head || i < self.tail
116.             }
117.         )
118.     }
119. 
120. 
121.     pub open spec fn is_checked_out(&self, i: nat) -> bool {
122.         self.producer == ProducerState::Producing(i)
123.         || self.consumer == ConsumerState::Consuming(i)
124.     }
125. 
126. 
127.     pub open spec fn valid_storage_at_idx(&self, i: nat) -> bool {
128.         if self.is_checked_out(i) {
129.             !self.storage.dom().contains(i)
130.         } else {
131.             self.storage.dom().contains(i)
132. 
133.             && self.storage.index(i).id() == self.backing_cells.index(i as int)
134. 
135.             && if self.in_active_range(i) {
136.                 self.storage.index(i).is_init()
137.             } else {
138.                 self.storage.index(i).is_uninit()
139.             }
140.         }
141.     }
142. 
143.     #[invariant]
144.     pub fn valid_storage_all(&self) -> bool {
145.         forall|i: nat| 0 <= i && i < self.len() ==>
146.             self.valid_storage_at_idx(i)
147.     }
148. 
149.     init!{
150.         initialize(backing_cells: Seq<CellId>, storage: Map<nat, cell::PointsTo<T>>) {
151. 
152.             require(
153.                 (forall|i: nat| 0 <= i && i < backing_cells.len() ==>
154.                     #[trigger] storage.dom().contains(i)
155.                     && storage.index(i).id() == backing_cells.index(i as int)
156.                     && storage.index(i).is_uninit())
157.             );
158.             require(backing_cells.len() > 0);
159. 
160.             init backing_cells = backing_cells;
161.             init storage = storage;
162.             init head = 0;
163.             init tail = 0;
164.             init producer = ProducerState::Idle(0);
165.             init consumer = ConsumerState::Idle(0);
166.         }
167.     }
168. 
169.     transition!{
170.         produce_start() {
171.             require(pre.producer.is_Idle());
172. 
173.             let tail = pre.producer.get_Idle_0();
174.             let head = pre.head;
175. 
176.             assert(0 <= tail && tail < pre.backing_cells.len());
177. 
178.             let next_tail = Self::inc_wrap(tail, pre.backing_cells.len());
179. 
180.             require(next_tail != head);
181. 
182.             update producer = ProducerState::Producing(tail);
183. 
184.             withdraw storage -= [tail => let perm] by {
185.                 assert(pre.valid_storage_at_idx(tail));
186.             };
187. 
188.             assert(
189.                 perm.id() == pre.backing_cells.index(tail as int)
190.                 && perm.is_uninit()
191.             ) by {
192.                 assert(!pre.in_active_range(tail));
193.                 assert(pre.valid_storage_at_idx(tail));
194.             };
195.         }
196.     }
197. 
198.     transition!{
199.         produce_end(perm: cell::PointsTo<T>) {
200.             require(pre.producer.is_Producing());
201.             let tail = pre.producer.get_Producing_0();
202. 
203.             assert(0 <= tail && tail < pre.backing_cells.len());
204. 
205.             let next_tail = Self::inc_wrap(tail, pre.backing_cells.len());
206. 
207. 
208. 
209.             require(perm.id() == pre.backing_cells.index(tail as int)
210.               && perm.is_init());
211. 
212.             update producer = ProducerState::Idle(next_tail);
213.             update tail = next_tail;
214. 
215.             deposit storage += [tail => perm] by { assert(pre.valid_storage_at_idx(tail)); };
216.         }
217.     }
218. 
219.     transition!{
220.         consume_start() {
221.             require(pre.consumer.is_Idle());
222. 
223.             let head = pre.consumer.get_Idle_0();
224.             let tail = pre.tail;
225. 
226.             assert(0 <= head && head < pre.backing_cells.len());
227. 
228.             require(head != tail);
229. 
230.             update consumer = ConsumerState::Consuming(head);
231. 
232. 
233.             birds_eye let perm = pre.storage.index(head);
234.             withdraw storage -= [head => perm] by {
235.                 assert(pre.valid_storage_at_idx(head));
236.             };
237. 
238.             assert(perm.id() == pre.backing_cells.index(head as int)) by {
239.                 assert(pre.valid_storage_at_idx(head));
240.             };
241.             assert(perm.is_init()) by {
242.                 assert(pre.in_active_range(head));
243.                 assert(pre.valid_storage_at_idx(head));
244.             };
245.         }
246.     }
247. 
248.     transition!{
249.         consume_end(perm: cell::PointsTo<T>) {
250.             require(pre.consumer.is_Consuming());
251.             let head = pre.consumer.get_Consuming_0();
252. 
253.             assert(0 <= head && head < pre.backing_cells.len());
254.             let next_head = Self::inc_wrap(head, pre.backing_cells.len());
255. 
256.             update consumer = ConsumerState::Idle(next_head);
257.             update head = next_head;
258. 
259.             require(perm.id() == pre.backing_cells.index(head as int)
260.               && perm.is_uninit());
261.             deposit storage += [head => perm] by { assert(pre.valid_storage_at_idx(head)); };
262.         }
263.     }
264. 
265.     #[inductive(initialize)]
266.     fn initialize_inductive(post: Self, backing_cells: Seq<CellId>, storage: Map<nat, cell::PointsTo<T>>) {
267.         admit()
268.     }
269.     #[inductive(produce_start)]
270.     fn produce_start_inductive(pre: Self, post: Self) {
271.     }
272.     #[inductive(produce_end)]
273.     fn produce_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
274.         admit()
275.     }
276.     #[inductive(consume_start)]
277.     fn consume_start_inductive(pre: Self, post: Self) {
278.         admit()
279.     }
280.     #[inductive(consume_end)]
281.     fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
282.         admit()
283.     }
284. }}
